\":\"custom\",\"typography_font_family\":\"Montserrat\",\"typography_font_size\":{\"unit\":\"px\",\"size\":20,\"sizes\":[]},\"typography_font_weight\":\"700\",\"title_color\":\"#060606\",\"__globals__\":{\"typography_typography\":\"\"}},\"elements\":[],\"widgetType\":\"heading\"},{\"id\":\"de6a7e8\",\"elType\":\"widget\",\"settings\":{\"editor\":\"<p>A energia n\\u00e3o se cria nem se destr\\u00f3i, apenas se transforma, mantendo-se constante em um sistema isolado.<\\/p>\",\"text_color\":\"#080808\",\"__globals__\":{\"typography_typography\":\"globals\\/typography?id=secondary\"}},\"elements\":[],\"widgetType\":\"text-editor\"}],\"isInner\":true}],\"isInner\":false},{\"id\":\"5bf0d5c\",\"elType\":\"container\",\"settings\":{\"flex_direction\":\"row\",\"flex_gap\":{\"unit\":\"px\",\"size\":30,\"column\":\"30\",\"row\":\"0\"},\"padding\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"100\",\"left\":\"0\",\"isLinked\":false}},\"elements\":[{\"id\":\"be69dd9\",\"elType\":\"container\",\"settings\":{\"flex_direction\":\"column\",\"content_width\":\"full\",\"width\":{\"unit\":\"%\",\"size\":\"50\"}},\"elements\":[{\"id\":\"4a48212\",\"elType\":\"widget\",\"settings\":{\"image\":{\"url\":\"http:\\/\\/localhost\\/fisica\\/wp-content\\/uploads\\/2025\\/07\\/fisica-quantica-og.png\",\"id\":91,\"size\":\"\",\"alt\":\"\",\"source\":\"library\"},\"align\":\"left\",\"image_border_radius\":{\"unit\":\"px\",\"top\":\"10\",\"right\":\"10\",\"bottom\":\"10\",\"left\":\"10\",\"isLinked\":true}},\"elements\":[],\"widgetType\":\"image\"}],\"isInner\":true},{\"id\":\"ff258c3\",\"elType\":\"container\",\"settings\":{\"flex_direction\":\"column\",\"content_width\":\"full\",\"width\":{\"unit\":\"%\",\"size\":\"50\"}},\"elements\":[{\"id\":\"99515f1\",\"elType\":\"widget\",\"settings\":{\"title\":\"\\ud83d\\udd2c O Mundo Invis\\u00edvel da F\\u00edsica Qu\\u00e2ntica\",\"typography_typography\":\"custom\",\"typography_font_family\":\"Montserrat\",\"typography_font_size\":{\"unit