 = document.createElement(\'div\');\\r\\n      dot.classList.add(\'carousel-dot\');\\r\\n      if (i === 0) dot.classList.add(\'active\');\\r\\n      dot.addEventListener(\'click\', () => goToSlide(i));\\r\\n      dotsNav.appendChild(dot);\\r\\n    });\\r\\n\\r\\n    const dots = Array.from(dotsNav.children);\\r\\n\\r\\n    function updateSlidePosition() {\\r\\n      track.style.transform = `translateX(-${currentIndex * 100}%)`;\\r\\n      dots.forEach(dot => dot.classList.remove(\'active\'));\\r\\n      dots[currentIndex].classList.add(\'active\');\\r\\n    }\\r\\n\\r\\n    function goToSlide(index) {\\r\\n      currentIndex = index;\\r\\n      updateSlidePosition();\\r\\n    }\\r\\n\\r\\n    function nextSlide() {\\r\\n      currentIndex = (currentIndex + 1) % slides.length;\\r\\n      updateSlidePosition();\\r\\n    }\\r\\n\\r\\n    function prevSlide() {\\r\\n      currentIndex = (currentIndex - 1 + slides.length) % slides.length;\\r\\n      updateSlidePosition();\\r\\n    }\\r\\n\\r\\n    nextButton.addEventListener(\'click\', nextSlide);\\r\\n    prevButton.addEventListener(\'click\', prevSlide);\\r\\n\\r\\n    \\/\\/ Auto play (opcional)\\r\\n    setInterval(nextSlide, 5000);\\r\\n  <\\/script>\\r\\n\\r\\n<\\/body>\\r\\n<\\/html>\\r\\n\"},\"elements\":[],\"widgetType\":\"html\"}],\"isInner\":false},{\"id\":\"0424637\",\"elType\":\"container\",\"settings\":{\"flex_direction\":\"row\",\"flex_justify_content\":\"center\"},\"elements\":[{\"id\":\"81001cd\",\"elType\":\"widget\",\"settings\":{\"shortcode\":\"[icones_servicos_uerj]\"},\"elements\":[],\"widgetType\":\"shortcode\"}],\"isInner\":false}]'),(2873,418,'_elementor_edit_mode','builder'),(2874,418,'_elementor_template_type','wp-page'),(2875,418,'_elementor_version','3.32.1'),(2876,418,'_wp_page_template','elementor_header_footer'),(2877,418,'_elementor_data','[{\"id\":\"8b71430\",\"elType\":\"container\",\"settings\":{\"flex_direction\":\"column\",\"content_width\":\"full\",\"boxed_width\":{\"unit\":\"px\",