r *\\/\\r\\n      background-position: center; \\/* \\ud83d\\udd39 Centraliza *\\/\\r\\n      background-repeat: no-repeat;\\/* \\ud83d\\udd39 Evita repeti\\u00e7\\u00e3o *\\/\\r\\n    }\\r\\n\\r\\n    \\/* \\ud83d\\udd39 Bot\\u00f5es de navega\\u00e7\\u00e3o *\\/\\r\\n    .carousel-button {\\r\\n      position: absolute;\\r\\n      top: 50%;\\r\\n      transform: translateY(-50%);\\r\\n      background: rgba(0,0,0,0.5);\\r\\n      border: none;\\r\\n      color: #fff;\\r\\n      font-size: 2rem;\\r\\n      padding: 0.5rem 1rem;\\r\\n      cursor: pointer;\\r\\n      border-radius: 50%;\\r\\n      z-index: 10;\\r\\n      transition: background 0.3s;\\r\\n    }\\r\\n\\r\\n    .carousel-button:hover {\\r\\n      background: rgba(0,0,0,0.8);\\r\\n    }\\r\\n\\r\\n    .carousel-button.prev { left: 20px; }\\r\\n    .carousel-button.next { right: 20px; }\\r\\n\\r\\n    \\/* \\ud83d\\udd39 Bolinhas indicadores *\\/\\r\\n    .carousel-dots {\\r\\n      position: absolute;\\r\\n      bottom: 15px;\\r\\n      left: 50%;\\r\\n      transform: translateX(-50%);\\r\\n      display: flex;\\r\\n      gap: 10px;\\r\\n    }\\r\\n\\r\\n    .carousel-dot {\\r\\n      width: 12px;\\r\\n      height: 12px;\\r\\n      background: rgba(255,255,255,0.6);\\r\\n      border-radius: 50%;\\r\\n      cursor: pointer;\\r\\n      transition: all 0.3s;\\r\\n    }\\r\\n\\r\\n    .carousel-dot.active {\\r\\n      background: #0072CE;\\r\\n      transform: scale(1.3); \\/* \\ud83d\\udd39 Bolinha ativa maior *\\/\\r\\n    }\\r\\n  <\\/style>\\r\\n<\\/head>\\r\\n<body>\\r\\n\\r\\n  <div class=\\\"carousel\\\">\\r\\n    <div class=\\\"carousel-track\\\">\\r\\n      <div class=\\\"carousel-slide\\\" style=\\\"background-image: url(\'http:\\/\\/localhost\\/fisica\\/wp-content\\/uploads\\/2025\\/09\\/imagem1.jpg\');\\\"><\\/div>\\r\\n      <div class=\\\"carousel-slide\\\" style=\\\"background-image: url(\'http:\\/\\/localhost\\/fisica\\/wp-content\\/uploads\\/2025\\/09\\/imagem2.jpg\');\\\"><\\/div>\\r\\n      <div class=\\\"carousel-slide\\\" style=\\\"background-image: url(\'https:\\/\\/picsum.photos\\/id\\/1019\\/1600\\/500\');\\\"><\\/div>\\r\\n    <\\/div>\\r\\n\\r\\n    <!-- Bot\\u00f5es -->\\r\\n    <button class=\\\"carousel-button prev\\\">&#10094;<\\/button>\\r\\n    <button class=\\\"carousel-button next\\\">&#10095;<\\/button>\\r\\n\\r\\n    <!-- Bolinhas -->\\r\\n    <div class=\\\"carousel-dots\\\"><\\/div>\\r\\n  <\\/div>\\r\\n\\r\\n  <script>\\r\\n    const track = document.querySelector(\'.carousel-track\');\\r\\n    const slides = Array.from(track.children);\\r\\n    const nextButton = document.querySelector(\'.carousel-button.next\');\\r\\n    const prevButton = document.querySelector(\'.carousel-button.prev\');\\r\\n    const dotsNav = document.querySelector(\'.carousel-dots\');\\r\\n\\r\\n    let currentIndex = 0;\\r\\n\\r\\n    \\/\\/ Criar bolinhas dinamicamente\\r\\n    slides.forEach((_, i) => {\\r\\n      const dot = document.createElement(\'div\');\\r\\n      dot.classList.add(\'carousel-dot\');\\r\\n      if (i === 0) dot.classList.add(\'active\');\\r\\n      dot.addEventListener(\'click\', () => goToSlide(i));\\r\\n      dotsNav.appendChild(dot);\\r\\n    });\\r\\n\\r\\n    const dots = Array.from(dotsNav.children);\\r\\n\\r\\n    function updateSlidePosition() {\\r\\n      track.style.transform = `translateX(-${currentIndex * 100}%)`;\\r\\n      dots.forEach(dot => dot.classList.remove(\'active\'));\\r\\n      dots[currentIndex].classList.add(\'active\');\\r\\n    }\\r\\n\\r\\n    function goToSlide(index) {\\r\\n      currentIndex = index;\\r\\n      updateSlidePosition();\\r\\n    }\\r\\n\\r\\n    function nextSlide() {\\r\\n      currentIndex = (currentIndex + 1) % slides.length;\\r\\n      updateSlidePosition();\\r\\n    }\\r\\n\\r\\n    function prevSlide() {\\r\\n      currentIndex = (currentIndex - 1 + slides.length) % slides.length;\\r\\n      updateSlidePosition();\\r\\n    }\\r\\n\\r\\n    nextButton.addEventListener(\'click\', nextSlide);\\r\\n    prevButton.addEventListener(\'click\', prevSlide);\\r\\n\\r\\n    \\/\\/ Auto play (opcional)\\r\\n    setInterval(nextSlide, 5000);\\r\\n  <\\/script>\\r\\n\\r\\n<\\/body>\\r\\n<\\/html>\\r\\n\"},\"elements\":[],\"widgetType\":\"html\"}],\"isInner\":false},{\"id\":\"653a035\",\"elType\":\"container\",\"settings\":{\"flex_direction\":\"column\",\"background_background\":\"gradient\",\"background_color_b\":\"\",\"__globals__\":{\"background_color\":\"\"},\"margin\":{\"unit\":\"px\",\"top\":\"100\",\"right\":\"0\",\"bottom\":\"50\",\"left\":\"0\",\"isLinked\":false},\"padding\":{\"unit\":\"px\",\"top\":\"100\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false},\"_flex_align_self\":\"center\"},\"elements\":[{\"id\":\"effc71e\",\"elType\":\"widget\",\"settings\":{\"title\":\"Eventos\",\"header_size\":\"h1\",\"align\":\"center\",\"typography_typography\":\"custom\",\"typography_font_family\":\"Montserrat\",\"typography_font_size\":{\"unit\":\"px\",\"size\":45,\"sizes\":[]},\"typography_font_weight\":\"bold\",\"text_shadow_text_shadow\":{\"horizontal\":7,\"vertical\":11,\"blur\":11,\"color\":\"rgba(0,0,0,0.3)\"},\"__globals__\":{\"typography_typography\":\"\",\"title_color\":\"globals\\/colors?id=f70c870\"}},\"elements\":[],\"widgetType\":\"heading\"}],\"isInner\":false},{\"id\":\"e0a170a\",\"elType\":\"container\",\"settings\":{\"flex_direction\":\"row\",\"flex_gap\":{\"unit\":\"px\",\"size\":40,\"column\":\"40\",\"row\":\"0\"},\"margin\":{\"unit\":\"px\",\"top\":\"100\",\"right\":\"0\",\"bottom\":\"100\",\"left\":\"0\",\"isLinked\":false}},\"elements\":[{\"id\":\"e2597eb\",\"elType\":\"container\",\"settings\":{\"flex_direction\":\"column\",\"content_width\":\"full\",\"width\":{\"unit\":\"%\",\"size\":\"50\"}},\"elements\":[{\"id\":\"23cb185\",\"elType\":\"widget\",\"settings\":{\"image\":{\"url\":\"http:\\/\\/localhost\\/fisica\\/wp-content\\/uploads\\/2025\\/09\\/WhatsApp-Image-2025-08-25-at-15.23.48.jpg\",\"id\":425,\"size\":\"