dex;\\r\\n      updateSlidePosition();\\r\\n    }\\r\\n\\r\\n    function nextSlide() {\\r\\n      currentIndex = (currentIndex + 1) % slides.length;\\r\\n      updateSlidePosition();\\r\\n    }\\r\\n\\r\\n    function prevSlide() {\\r\\n      currentIndex = (currentIndex - 1 + slides.length) % slides.length;\\r\\n      updateSlidePosition();\\r\\n    }\\r\\n\\r\\n    function resetAutoPlay() {\\r\\n      clearInterval(autoPlay);\\r\\n      autoPlay = setInterval(nextSlide, 5000);\\r\\n    }\\r\\n\\r\\n    nextButton.addEventListener(\'click\', () => {\\r\\n      nextSlide();\\r\\n      resetAutoPlay();\\r\\n    });\\r\\n\\r\\n    prevButton.addEventListener(\'click\', () => {\\r\\n      prevSlide();\\r\\n      resetAutoPlay();\\r\\n    });\\r\\n  <\\/script>\\r\\n\\r\\n<\\/body>\\r\\n<\\/html>\"},\"elements\":[],\"widgetType\":\"html\"}],\"isInner\":false},{\"id\":\"653a035\",\"elType\":\"container\",\"settings\":{\"flex_direction\":\"column\",\"background_background\":\"gradient\",\"background_color_b\":\"\",\"__globals__\":{\"background_color\":\"globals\\/colors?id=41c3483\"},\"margin\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false},\"padding\":{\"unit\":\"px\",\"top\":\"100\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false},\"_flex_align_self\":\"center\"},\"elements\":[{\"id\":\"effc71e\",\"elType\":\"widget\",\"settings\":{\"title\":\"Eventos\",\"header_size\":\"h1\",\"align\":\"center\",\"typography_typography\":\"custom\",\"typography_font_family\":\"Montserrat\",\"typography_font_size\":{\"unit\":\"px\",\"size\":45,\"sizes\":[]},\"typography_font_weight\":\"bold\",\"text_shadow_text_shadow\":{\"horizontal\":7,\"vertical\":11,\"blur\":11,\"color\":\"rgba(0,0,0,0.3)\"},\"__globals__\":{\"typography_typography\":\"\",\"title_color\":\"\"},\"title_color\":\"#003BB1\"},\"elements\":[],\"widgetType\":\"heading\"}],\"isInner\":false},{\"id\":\"e0a170a\",\"elType\":\"container\",\"settings\":{\