:37:\"2026/04/PHOTO-2026-03-18-16-06-53.jpg\";s:8:\"filesize\";i:57237;s:5:\"sizes\";a:0:{}s:10:\"image_meta\";a:12:{s:8:\"aperture\";s:1:\"0\";s:6:\"credit\";s:0:\"\";s:6:\"camera\";s:0:\"\";s:7:\"caption\";s:0:\"\";s:17:\"created_timestamp\";s:1:\"0\";s:9:\"copyright\";s:0:\"\";s:12:\"focal_length\";s:1:\"0\";s:3:\"iso\";s:1:\"0\";s:13:\"shutter_speed\";s:1:\"0\";s:5:\"title\";s:0:\"\";s:11:\"orientation\";s:1:\"0\";s:8:\"keywords\";a:0:{}}}'),(6288,1054,'_thumbnail_id','1053'),(6290,1056,'_elementor_template_type','wp-page'),(6291,1056,'_elementor_version','3.32.1'),(6292,1056,'_wp_page_template','elementor_header_footer'),(6293,1056,'_elementor_data','[{\"id\":\"homehero1\",\"elType\":\"container\",\"settings\":{\"content_width\":\"full\",\"flex_direction\":\"column\",\"margin\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false},\"padding\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false}},\"elements\":[{\"id\":\"homehtml1\",\"elType\":\"widget\",\"settings\":{\"html\":\"<section class=\\\"fisica-home-hero\\\">\\n  <div class=\\\"fisica-home-hero__inner\\\">\\n    <div class=\\\"fisica-home-hero__carousel fisica-home-carousel\\\" data-carousel>\\n      <div class=\\\"fisica-home-carousel__track\\\">\\n        <a class=\\\"fisica-home-carousel__slide\\\" href=\\\"http://localhost/fisica/index.php/visita-tecnica-inpe-2026/\\\" style=\\\"background-image:url(\'http://localhost/fisica/wp-content/uploads/2026/03/PHOTO-2026-03-18-16-06-52.jpg\');\\\">\\n          <div class=\\\"fisica-home-carousel__content\\\">\\n            <span class=\\\"fisica-home-carousel__label\\\">Notícia em destaque</span>\\n            <h3>Visita técnica ao Instituto Nacional de Pesquisas Espaciais</h3>\\n            <p>Com professores e estudantes do Instituto de Física da UERJ, a atividade reforçou integração acadêmica, formação e aproximação com centros de excelência.</p>\\n          </div>\\n        </a>\\n        <a class=\\\"fisica-home-carousel__slide\\\" href=\\\"http://localhost/fisica/noticia/noticia-2\\\" style=\\\"background-image:url(\'http://localhost/fisica/wp-content/uploads/2026/03/PHOTO-2026-03-18-16-24-39.jpg\');\\\">\\n          <div class=\\\"fisica-home-carousel__content\\\">\\n            <span class=\\\"fisica-home-carousel__label\\\">Infraestrutura</span>\\n            <h3>Novos equipamentos para os laboratórios de Mecânica</h3>\\n            <p>Os investimentos ampliam as condições de ensino experimental e fortalecem a formação prática nos cursos atendidos pelo instituto.</p>\\n          </div>\\n        </a>\\n        <a class=\\\"fisica-home-carousel__slide\\\" href=\\\"http://localhost/fisica/index.php/recepcao-dos-estudantes-2026-1/\\\" style=\\\"background-image:url(\'http://localhost/fisica/wp-content/uploads/2026/04/PHOTO-2026-03-18-16-03-28.jpg\');\\\">\\n          <div class=\\\"fisica-home-carousel__content\\\">\\n            <span class=\\\"fisica-home-carousel__label\\\">Vida acadêmica</span>\\n            <h3>Recepção dos Estudantes 2026/1 integra calouros, veteranos e comunidade acadêmica</h3>\\n            <p>Programação de acolhimento aproximou estudantes, egressos, laboratórios e iniciativas de cuidado com a saúde mental no início do período letivo.</p>\\n          </div>\\n        </a>\\n      </div>\\n      <div class=\\\"fisica-home-carousel__controls\\\">\\n        <button class=\\\"fisica-home-carousel__button\\\" type=\\\"button\\\" data-carousel-prev aria-label=\\\"Slide anterior\\\">&#10094;</button>\\n        <div class=\\\"fisica-home-carousel__dots\\\" data-carousel-dots></div>\\n        <button class=\\\"fisica-home-carousel__button\\\" type=\\\"button\\\" data-carousel-next aria-label=\\\"Próximo slide\\\">&#10095;</button>\\n      </div>\\n    </div>\\n  </div>\\n</section>\\n\\n<script>\\n(() => {\\n  const root = document.querySelector(\'[data-carousel]\');\\n  if (!root || root.dataset.ready === \'true\') {\\n    return;\\n  }\\n  root.dataset.ready = \'true\';\\n\\n  const track = root.querySelector(\'.fisica-home-carousel__track\');\\n  const slides = Array.from(root.querySelectorAll(\'.fisica-home-carousel__slide\'));\\n  const next = root.querySelector(\'[data-carousel-next]\');\\n  const prev = root.querySelector(\'[data-carousel-prev]\');\\n  const dotsWrap = root.querySelector(\'[data-carousel-dots]\');\\n\\n  if (!track || !slides.length || !next || !prev || !dotsWrap) {\\n    return;\\n  }\\n\\n  let index = 0;\\n  let timer = null;\\n\\n  const dots = slides.map((_, i) => {\\n    const dot = document.createElement(\'button\');\\n    dot.type = \'button\';\\n    dot.className = \'fisica-home-carousel__dot\';\\n    dot.setAttribute(\'aria-label\', `Ir para slide ${i + 1}`);\\n    dot.addEventListener(\'click\', () => {\\n      goTo(i);\\n      restart();\\n    });\\n    dotsWrap.appendChild(dot);\\n    return dot;\\n  });\\n\\n  function render() {\\n    track.style.transform = `translateX(-${index * 100}%)`;\\n    dots.forEach((dot, dotIndex) => {\\n      dot.classList.toggle(\'is-active\', dotIndex === index);\\n    });\\n  }\\n\\n  function goTo(nextIndex) {\\n    index = (nextIndex + slides.length) % slides.length;\\n    render();\\n  }\\n\\n  function restart() {\\n    window.clearInterval(timer);\\n    timer = window.setInterval(() => goTo(index + 1), 5500);\\n  }\\n\\n  next.addEventListener(\'click\', () => {\\n    goTo(index + 1);\\n    restart();\\n  });\\n\\n  prev.addEventListener(\'click\', () => {\\n    goTo(index - 1);\\n    restart();\\n  });\\n\\n  render();\\n  restart();\\n})();\\n</script>\"},\"elements\":[],\"widgetType\":\"html\"}],\"isInner\":false},{\"id\":\"homeevents1\",\"elType\":\"container\",\"settings\":{\"content_width\":\"full\",\"flex_direction\":\"column\"},\"elements\":[{\"id\":\"eventhtml1\",\"elType\":\"widget\",\"settings\":{\"html\":\"<section class=\\\"fisica-home-section\\\">\\n  <div class=\\\"fisica-home-se